#!/usr/bin/env python3
"""Generate private numeric parsing tables from Unicode 16.0.0."""

import argparse
from pathlib import Path
import unicodedata


UNICODE_VERSION = "16.0.0"
OUTPUT = Path(__file__).resolve().parents[1] / "src/util/num_parse_unicode.inc"


def generate():
    lines = [
        "// Generated by tools/generate_numeric_unicode_tables.py.",
        f"// Unicode {UNICODE_VERSION}; do not edit by hand.",
        "",
        "static constexpr uint32_t decimal_zero_codepoints[] = {",
    ]
    for codepoint in range(0x110000):
        if unicodedata.decimal(chr(codepoint), None) == 0:
            assert all(
                unicodedata.decimal(chr(codepoint + offset), None) == offset
                for offset in range(10)
            )
            lines.append(
                f"    0x{codepoint:04x},  // {unicodedata.name(chr(codepoint))}"
            )
    lines += ["};", "", "static constexpr uint32_t numeric_whitespace_codepoints[] = {"]
    for codepoint in range(0x80, 0x110000):
        if chr(codepoint).isspace():
            name = unicodedata.name(chr(codepoint), "CONTROL")
            lines.append(f"    0x{codepoint:04x},  // {name}")
    lines += ["};", ""]
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    if unicodedata.unidata_version != UNICODE_VERSION:
        parser.error(
            f"requires Unicode {UNICODE_VERSION}; found {unicodedata.unidata_version}"
        )
    content = generate()
    if args.check:
        if OUTPUT.read_text() != content:
            parser.error(f"{OUTPUT} is out of date")
    else:
        OUTPUT.write_text(content)


if __name__ == "__main__":
    main()
